(() => {
'use strict';
const $=s=>document.querySelector(s),c=window.HVT,form=$('#memberForm');
let preview=false,user=null,rows=[],page=1,hasMore=false,editing=null,deleting=null,sequence=0,busy=false;
function status(text,error=false){$('#membersStatus').textContent=text;$('#membersStatus').classList.toggle('error',error)}
function controls(flag){busy=flag;$('#memberFields').disabled=flag;$('#reloadMembers').disabled=flag||preview;$('#membersPrevious').disabled=flag||preview||page===1;$('#membersNext').disabled=flag||preview||!hasMore;$('#saveMember').disabled=flag||preview;$('#memberList').querySelectorAll('button').forEach(btn=>btn.disabled=flag)}
async function request(body){try{return await c.api('/functions/v1/manage-members',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}catch(error){if(error instanceof TypeError||/Failed to fetch|NetworkError|Load failed/i.test(error.message))throw Error('Không kết nối được manage-members. Cần triển khai hàm trong Supabase và cho phép tên miền '+location.origin+'. Xem Hướng dẫn → Cập nhật V6.');if(error.status===404)throw Error('Chưa tìm thấy Edge Function manage-members. Hãy triển khai hàm theo hướng dẫn V6.');if(error.status===401)throw Error('Phiên hết hạn hoặc cấu hình JWT của hàm chưa đúng. Đăng nhập lại; nếu vẫn lỗi, triển khai bằng cấu hình supabase/config.toml của V6.');throw error}}
function resetForm(){editing=null;form.reset();form.elements.password.required=true;$('#memberFormTitle').textContent='Thêm thành viên';$('#passwordHint').textContent='(12–128 ký tự)';$('#saveMember').textContent='Thêm tài khoản';$('#cancelMemberEdit').hidden=true;controls(false)}
function render(){const esc=c.esc;$('#memberList').innerHTML=rows.length?rows.map(row=>`<div class="member-row"><div><strong>${esc(row.name||row.email)}</strong><p>${esc(row.email)}</p><small>${row.role==='admin'?'Quản trị viên':'Thành viên'}${row.id===user?.id?' · Bạn':''}</small></div><div class="row-actions"><button type="button" class="text-link" data-member-edit="${esc(row.id)}">Sửa</button>${row.id!==user?.id?`<button type="button" class="text-link delete" data-member-delete="${esc(row.id)}">Xóa</button>`:''}</div></div>`).join(''):'<p class="hint">Chưa có tài khoản trong danh sách.</p>';$('#membersPage').textContent='Trang '+page;controls(busy)}
async function load(){if(preview){rows=[];hasMore=false;render();status('Xem trước. Chức năng tài khoản cần Edge Function manage-members của Supabase.');return}const token=++sequence;controls(true);status('Đang tải thành viên…');try{const result=await request({action:'list',page});if(token!==sequence)return;rows=result.users||[];hasMore=result.hasMore;user={...user,id:result.actor};render();status('Chỉ quản trị viên được quản lý tài khoản. Không thể tự xóa hoặc tự thu hồi quyền quản trị.')}catch(error){if(token!==sequence)return;rows=[];render();status('Chưa tải được thành viên. '+error.message,true)}finally{if(token===sequence)controls(false)}}
$('#reloadMembers').onclick=load;$('#membersPrevious').onclick=()=>{if(page>1){page--;load()}};$('#membersNext').onclick=()=>{if(hasMore){page++;load()}};$('#cancelMemberEdit').onclick=resetForm;
$('#memberList').onclick=e=>{if(busy)return;const edit=e.target.closest('[data-member-edit]'),del=e.target.closest('[data-member-delete]');if(edit){editing=rows.find(row=>row.id===edit.dataset.memberEdit);if(!editing)return;form.elements.name.value=editing.name;form.elements.email.value=editing.email;form.elements.role.value=editing.role;form.elements.password.value='';form.elements.password.required=false;$('#memberFormTitle').textContent='Chỉnh sửa tài khoản';$('#passwordHint').textContent='(để trống để giữ mật khẩu hiện tại)';$('#saveMember').textContent='Lưu thay đổi';$('#cancelMemberEdit').hidden=false}if(del){deleting=rows.find(row=>row.id===del.dataset.memberDelete);$('#memberDeleteName').textContent=deleting?.email||'';$('#confirmMemberEmail').value='';$('#memberDeleteDialog').showModal()}};
form.onsubmit=async e=>{e.preventDefault();if(preview||busy||!c.hasSession())return;const f=new FormData(form),record={action:editing?'update':'create',...(editing?{id:editing.id}:{}),name:f.get('name').trim(),email:f.get('email').trim(),role:f.get('role'),password:f.get('password')};if(editing?.id===user?.id&&record.role!=='admin'){status('Không thể tự thu hồi quyền quản trị của mình.',true);return}controls(true);try{await request(record);const selfChanged=editing?.id===user?.id&&(record.email!==editing.email||record.password);resetForm();await load();status(selfChanged?'Đã cập nhật tài khoản của bạn. Đăng xuất rồi đăng nhập lại với thông tin mới.':'Đã lưu tài khoản thành viên.')}catch(error){form.elements.password.value='';status(error.message,true)}finally{controls(false)}};
$('#cancelMemberDelete').onclick=()=>$('#memberDeleteDialog').close();$('#confirmMemberDelete').onclick=async()=>{if(!deleting||preview||busy)return;const email=$('#confirmMemberEmail').value.trim();if(email.toLowerCase()!==deleting.email.toLowerCase()){status('Nhập đúng email tài khoản trong ô xác nhận.',true);return}$('#confirmMemberDelete').disabled=true;controls(true);try{await request({action:'delete',id:deleting.id,confirm_email:email});$('#memberDeleteDialog').close();if(editing?.id===deleting.id)resetForm();deleting=null;await load();status('Đã xóa tài khoản. Các bài đã đăng vẫn được giữ.')}catch(error){status(error.message,true);$('#memberDeleteDialog').close()}finally{$('#confirmMemberDelete').disabled=false;controls(false)}};
window.HVTMembers={open(next){preview=!!next.preview;user=next.user;resetForm();load()},reset(){sequence++;rows=[];page=1;hasMore=false;user=null;resetForm();$('#memberList').innerHTML='';$('#memberDeleteDialog').close()}};
})();
